INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Ananya Panday', 'Ananya Panday', 'ananya-panday', 'Female', 'Acting', '1998-10-30', 'Mumbai, Maharashtra, India', 'Ananya Panday (born 30 October 1998) is a leading Indian actress working in Hindi cinema. Born to actor Chunky Panday, she made her acting debut with the teen film Student of the Year 2 (2019), winning the Filmfare Award for Best Female Debut. She has earned widespread acclaim for her versatile performances in the romantic drama Gehraiyaan (2022), the coming-of-age drama Kho Gaye Hum Kahan (2023), the hit comedy Dream Girl 2, the Amazon Prime series Call Me Bae (2024), and Vikramaditya Motwane\'s cyber-thriller CTRL (2024).', 'people/photos/ananya-panday.jpg', 'https://www.instagram.com/ananyapanday', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/ananyapanday\",\"twitter\":\"https:\\/\\/twitter.com\\/ananyapandayy\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm9153503\\/\"}', 1, 'active', 1, @now, @now)
