-- Nia Long (Born: October 30)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Nia Long', 'Nia Long', 'nia-long', 'Female', 'Acting', '1970-10-30', 'Brooklyn, New York, USA', 'Nia Talita Long (born October 30, 1970) is an acclaimed American actress. Known for her work in Black cinema, Long rose to prominence starring as Brandi in John Singleton\'s classic Boyz n the Hood (1991) and as Debbie in Friday (1995). She gained further stardom in Love Jones (1997), The Best Man (1999), Big Momma\'s House (2000), The Best Man Holiday (2013), and NCIS: Los Angeles. Over her career, she has received three NAACP Image Awards and a Black Reel Award.', 'people/photos/nia-long.jpg', 'https://www.instagram.com/iamnialong', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/iamnialong\",\"twitter\":\"https:\\/\\/twitter.com\\/NiaLong\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0000505\\/\"}', 1, 'active', 1, @now, @now)
