-- Gael García Bernal (Born: October 30)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Gael García Bernal', 'Gael García Bernal', 'gael-garcia-bernal', 'Male', 'Acting', '1978-10-30', 'Guadalajara, Jalisco, Mexico', 'Gael García Bernal (born 30 October 1978) is an internationally acclaimed Mexican actor and director. He gained worldwide recognition for his breakout performances in Alejandro González Iñárritu\'s Amores Perros (2000) and Alfonso Cuarón\'s Y Tu Mamá También (2001). He famously portrayed Che Guevara in The Motorcycle Diaries (2004) and starred in Babel (2006), Bad Education (2004), and voiced Héctor in Pixar\'s Oscar-winning Coco (2017). He won a Golden Globe Award for Mozart in the Jungle and starred in Marvel Studios\' Werewolf by Night (2022).', 'people/photos/gael-garcia-bernal.jpg', 'https://twitter.com/GaelGarciaB', '{\"twitter\":\"https:\\/\\/twitter.com\\/GaelGarciaB\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0305558\\/\"}', 1, 'active', 1, @now, @now)
