-- Henry Winkler (Born: October 30)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Henry Winkler', 'Henry Winkler', 'henry-winkler', 'Male', 'Acting', '1945-10-30', 'Manhattan, New York City, USA', 'Henry Franklin Winkler (born October 30, 1945) is a legendary American actor, comedian, director, and producer. He rose to international stardom as the charismatic greaser Arthur \"Fonzie\" Fonzarelli on the historic sitcom Happy Days (1974–1984), for which he won two Golden Globe Awards. In recent years, he received critical acclaim and a Primetime Emmy Award for his role as Gene Cousineau in the HBO dark comedy series Barry (2018–2023). His other beloved roles include Arrested Development, Parks and Recreation, and Wes Anderson\'s The French Dispatch.', 'people/photos/henry-winkler.jpg', 'https://twitter.com/hwinkler4real', '{\"twitter\":\"https:\\/\\/twitter.com\\/hwinkler4real\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0001857\\/\"}', 1, 'active', 1, @now, @now)
