-- Abhijeet Bhattacharya (Born: October 30)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Abhijeet Bhattacharya', 'Abhijeet', 'abhijeet-bhattacharya', 'Male', 'Sound', '1958-10-30', 'Kanpur, Uttar Pradesh, India', 'Abhijeet Bhattacharya (born 30 October 1958), better known mononymously as Abhijeet, is a prominent Indian playback singer who has recorded thousands of chart-topping songs in Hindi and Bengali cinema. Known as the iconic voice of superstar Shah Rukh Khan throughout the 1990s and early 2000s, his legendary hits include songs from Baaghi, Yes Boss (winning the Filmfare Award for Best Playback Singer for \"Main Koi Aisa Geet Gaoon\"), Main Hoon Na, Baadshah, Josh, Dhadkan, Chalte Chalte, and Om Shanti Om.', 'people/photos/abhijeet-bhattacharya.jpg', 'https://www.instagram.com/abhijeetbhattacharya', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/abhijeetbhattacharya\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0008892\\/\"}', 1, 'active', 1, @now, @now)
