-- Matthew Morrison (Born: October 30)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Matthew Morrison', 'Matthew Morrison', 'matthew-morrison', 'Male', 'Acting', '1978-10-30', 'Fort Ord, California, USA', 'Matthew James Morrison (born October 30, 1978) is an Emmy and Golden Globe-nominated American actor, dancer, and singer-songwriter. He gained worldwide fame for his starring role as high school glee club director Will Schuester in the Fox musical comedy-drama series Glee (2009–2015). A celebrated Broadway headliner, Morrison originated the role of Link Larkin in Hairspray (2002) and starred in The Light in the Piazza (Tony nomination) and Finding Neverland.', 'people/photos/matthew-morrison.jpg', 'https://www.instagram.com/matthewmorrison', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/matthewmorrison\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm1060388\\/\"}', 1, 'active', 1, @now, @now)
