-- Ashley Graham (Born: October 30)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Ashley Graham', 'Ashley Graham', 'ashley-graham', 'Female', 'Modeling', '1987-10-30', 'Lincoln, Nebraska, USA', 'Ashley Graham (born October 30, 1987) is a globally celebrated American supermodel, author, and television personality. A pioneering champion of body positivity and diversity in fashion, she became the first size-16 model to appear on the cover of the Sports Illustrated Swimsuit Issue in 2016. She has graced the covers of Vogue, Harper\'s Bazaar, Glamour, and Elle, and has served as a judge on America\'s Next Top Model and host of the American Beauty Star series.', 'people/photos/ashley-graham.jpg', 'https://www.instagram.com/ashleygraham', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/ashleygraham\",\"twitter\":\"https:\\/\\/twitter.com\\/theashleygraham\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm6820542\\/\"}', 1, 'active', 1, @now, @now)
